class GSLVector(ctypes.Structure):
  _fields_ = [("data", ctypes.POINTER(ctypes.c_double)), ("size", ctypes.c_int)]

def vector_add(a, b):
  result = GSLVector()
  result.size = a.size
  result.data = (ctypes.c_double * result.size)(*) 
  for i in range(result.size):
    result.data[i] = a.data[i] + b.data[i]
  return result

def gsl_vector_add(a, b):
  return vector_add(a, b)


