def compute_gensymm_eigenvalues(A: np.ndarray, B: np.ndarray) -> List[float]:
    assert A.shape == B.shape,"Matrices A and B must have the same dimensions"
    workspace = gsl.gsl_eigen_gensymm_alloc(A.shape[0])
    A_gsl = numpy_to_gsl_matrix(A)
    B_gsl = numpy_to_gsl_matrix(B)
    result = gsl.gsl_eigen_gensymm(A_gsl, B_gsl, workspace)
    eigenvalues = (gsl.gsl_vector_get_array(result.eigenvalues))
    return [eigenvalue for eigenvalue in eigenvalues]

