gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLMatrix:
    def __init__(self, rows: int, cols: int):
        self.ptr = gsl.gsl_matrix_alloc(rows, cols)

    def set(self, i: int, j: int, value: float) -> None:
        gsl.gsl_matrix_set(self.ptr, i, j, value)

    def get(self, i: int, j: int) -> float:
        return gsl.gsl_matrix_get(self.ptr, i, j)

class GSLPermutation:
    def __init__(self, size: int):
        self.ptr = gsl.gsl_permutation_alloc(size)

    def get(self, i: int) -> int:
        return gsl.gsl_permutation_get(self.ptr, i)

def cholesky_decomposition(input_matrix: list[list[float]]) -> Tuple[list[list[float]], list[int]]:
    rows = len(input_matrix)
    cols = len(input_matrix[0])
    assert rows == cols

    matrix = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            matrix.set(i, j, input_matrix[i][j])

    perm = GSLPermutation(rows)
    gsl.gsl_linalg_pcholesky_decomp(matrix.ptr, perm.ptr)

    result_matrix = [[matrix.get(i, j) for j in range(cols)] for i in range(rows)]
    permutation = [perm.get(i) for i in range(rows)]
    return result_matrix, permutation

if __name__ == "__main__":
    input_matrix = [[4, 2], [2, 3]]
    result_matrix, permutation = cholesky_decomposition(input_matrix)
    print(f"Result matrix: {result_matrix}")
    print(f"Permutation: {permutation}")

