  return gsl.gsl_matrix_alloc(len(matrix), len(matrix[0]))

def vector_to_gsl(vector):
  return gsl.gsl_vector_alloc(len(vector))

def gsl_matrix_to_list(matrix):
  rows = matrix.size
  cols = matrix.ptr[0].size
  result = [[0 for _ in range(cols)] for _ in range(rows)]
  for i in range(rows):
    for j in range(cols):
      result[i][j] = matrix.ptr[i * cols + j]
  return result

def gsl_vector_to_list(vector):
  return [vector.ptr[i] for i in range(vector.size)]

def ql_decomposition_and_unpack(A, tau):
  A_gsl = matrix_to_gsl(A)
  tau_gsl = vector_to_gsl(tau)
  M = gsl.gsl_matrix_alloc(len(A), len(A[0]))
  L = gsl.gsl_matrix_alloc(len(A), len(A[0]))
  gsl.gsl_linalg_QL_decomp(M, A_gsl, tau_gsl)
  Q = gsl_matrix_to_list(M)
  L = gsl_matrix_to_list(L)
  return Q, L
