from typing import List
def cholesky_decomposition(matrix: List[List[float]]) -> List[List[float]]:
    try:
        ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
        class GSLMatrix(ctypes.Structure):
            pass
        GSLMatrix._fields_ = ['data', 'size1', 'size2', 'type']
        matrix_ptr = (GSLMatrix * len(matrix))[0]
        for i in range(len(matrix)):
            for j in range(len(matrix[i])):
                matrix_ptr.data[i * len(matrix) + j] = matrix[i][j]
        matrix_ptr.size1 = len(matrix)
        matrix_ptr.size2 = len(matrix)
        matrix_ptr.type = 1
        gsl.gsl_linalg_cholesky_decomp(matrix_ptr)
        result = [[0 for _ in range(len(matrix))] for _ in range(len(matrix))]
        for i in range(len(matrix)):
            for j in range(i + 1):
                result[i][j] = matrix_ptr.data[i * len(matrix) + j]
        return result
