            if len(data) > i:
                self.data[i] = data[i]
            else:
                self.data[i] = 0

    def from_list(self, lst):
        if len(lst) != self.size:
            raise ValueError("List length does not match vector size")
        for i in range(len(lst)):
            self.data[i] = lst[i]

